function ButtonLink({ href, children, light = false, testId }: { href: string; children: ReactNode; light?: boolean; testId: string }) {
  return <Link href={href} className={`inline-flex items-center justify-center gap-2 rounded-full px-5 py-3.5 text-sm font-bold transition-all hover:-translate-y-0.5 ${light ? 'bg-[hsl(var(--card))] text-[hsl(var(--foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`} data-testid={testId}>{children}<ArrowUpRight size={16} /></Link>;
}

function ExternalButton({ href, children, light = false, testId }: { href: string; children: ReactNode; light?: boolean; testId: string }) {
  return <a href={href} target="_blank" rel="noreferrer" className={`inline-flex items-center justify-center gap-2 rounded-full px-5 py-3.5 text-sm font-bold transition-all hover:-translate-y-0.5 ${light ? 'bg-[hsl(var(--card))] text-[hsl(var(--foreground))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]'}`} data-testid={testId}>{children}<ExternalLink size={15} /></a>;
}

